package dev.cardadvisor.domain;
import org.junit.jupiter.api.Test;import java.time.*;import static org.junit.jupiter.api.Assertions.*;
class ActualQualificationTest{
 @Test void registrationGraceCrossesYearAndEndsAtNextMonthEnd(){var date=LocalDate.of(2025,12,31);assertEquals(1,ActualQualification.calculate(ActualCardRules.KB,YearMonth.of(2026,1),0L,date).tier());assertEquals(0,ActualQualification.calculate(ActualCardRules.KB,YearMonth.of(2026,2),0L,date).tier());}
 @Test void unknownPerformanceIsNotZeroEvenDuringGrace(){var value=ActualQualification.calculate(ActualCardRules.GO,YearMonth.of(2026,2),null,LocalDate.of(2026,1,1));assertTrue(value.qualified());assertNull(value.tier());assertEquals(1,value.minimumTier());assertNull(ActualQualification.calculate(ActualCardRules.GO,YearMonth.of(2026,3),null,null).qualified());}
 @Test void tiersAndHigherPerformanceSurviveGrace(){var m=YearMonth.of(2026,2);assertEquals(0,ActualQualification.calculate(ActualCardRules.KB,m,499999L,null).tier());assertEquals(1,ActualQualification.calculate(ActualCardRules.KB,m,500000L,null).tier());assertEquals(2,ActualQualification.calculate(ActualCardRules.KB,m,1000000L,null).tier());assertEquals(3,ActualQualification.calculate(ActualCardRules.KB,m,1500000L,m.atDay(1)).tier());assertEquals(0,ActualQualification.calculate(ActualCardRules.GO,m,199999L,null).tier());assertEquals(1,ActualQualification.calculate(ActualCardRules.GO,m,200000L,null).tier());assertEquals(2,ActualQualification.calculate(ActualCardRules.GO,m,500000L,m.atDay(1)).tier());}
 @Test void logHasNoDomesticPerformanceThresholdAndNegativeMonthDoesNotQualify(){assertTrue(ActualQualification.calculate(ActualCardRules.LOG,YearMonth.of(2026,2),null,null).qualified());assertFalse(ActualQualification.calculate(ActualCardRules.KB,YearMonth.of(2026,2),-100L,null).qualified());}
}
